@Service
public class ContentEventProducer {
    private static final Logger log = LoggerFactory.getLogger(ContentEventProducer.class);
    private final KafkaTemplate<String, ContentUpdatedEvent> kafkaTemplate;

    public ContentEventProducer(KafkaTemplate<String, ContentUpdatedEvent> kafkaTemplate) {
        this.kafkaTemplate = kafkaTemplate;
    }

    public void publish(ContentUpdatedEvent event) {
        ProducerRecord<String, ContentUpdatedEvent> record =
                new ProducerRecord<>("content-events", event.slug(), event);
        kafkaTemplate.send(record).whenComplete((result, ex) -> {
            if (ex != null) {
                log.error("发送失败 slug={}", event.slug(), ex);
                return;
            }
            var meta = result.getRecordMetadata();
            log.info("写入 partition={} offset={}", meta.partition(), meta.offset());
        });
    }
}

@Component
public class ContentEventConsumer {
    private final ProcessedEventRepository processed;

    public ContentEventConsumer(ProcessedEventRepository processed) {
        this.processed = processed;
    }

    @KafkaListener(topics = "content-events", groupId = "learn-hub-search")
    public void onMessage(ConsumerRecord<String, ContentUpdatedEvent> record, Acknowledgment ack) {
        String eventId = record.value().eventId();
        if (processed.existsByEventId(eventId)) {
            ack.acknowledge();
            return;
        }
        processed.save(eventId);
        ack.acknowledge();
    }
}
